use std :: path :: Path ; use crate :: { Match , MatchResult } ; # [doc = " Truncates a key string for display purposes"] # [doc = ""] # [doc = " If the key length is 20 characters or less, returns it unchanged."] # [doc = " Otherwise, shows the first 13 characters and last 4 characters with \"...\" in"] # [doc = " between."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `key` - The key string to truncate"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A truncated version of the key for safe display"] pub use forge_domain :: truncate_key ; use sha2 :: { Digest , Sha256 } ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; # [doc = " Formats a path for display, converting absolute paths to relative when"] # [doc = " possible"] # [doc = ""] # [doc = " If the path starts with the current working directory, returns a"] # [doc = " relative path. Otherwise, returns the original absolute path."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `path` - The path to format"] # [doc = " * `cwd` - The current working directory path"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A formatted path string"] pub fn format_display_path (path : & Path , cwd : & Path) -> String { let display_path = if path . starts_with (cwd) { match path . strip_prefix (cwd) { Ok (rel_path) => rel_path . display () . to_string () , Err (_) => path . display () . to_string () , } } else { path . display () . to_string () } ; if display_path . is_empty () { "." . to_string () } else { display_path } }